<?php
declare(strict_types=1);require_once __DIR__.'/functions.php';require_login();$pdo=db();$total=(int)$pdo->query('SELECT COUNT(*) FROM students')->fetchColumn();$q=$pdo->query('SELECT status,COUNT(*) total FROM attendance_logs WHERE `date`=CURDATE() GROUP BY status');$counts=['Present'=>0,'Late'=>0,'Absent'=>0];foreach($q as $r)$counts[$r['status']]=(int)$r['total'];$recent=$pdo->query('SELECT u.name,s.student_id_no,s.course_year,a.status,a.time_in,a.`date` FROM attendance_logs a JOIN students s ON s.id=a.student_id JOIN users u ON u.id=s.user_id ORDER BY a.`date` DESC,a.time_in DESC LIMIT 7')->fetchAll();page_start('Overview','dashboard.php');
?><div class="page-heading"><div><p class="overline"><?=strtoupper(date('l, F j, Y'))?></p><h1>Good day, <?=e(explode(' ',current_user()['name'])[0])?> <span class="wave">✦</span></h1><p class="heading-subtitle">Here’s what’s happening in your classroom today.</p></div><a href="attendance_logs.php" class="btn btn-primary heading-action"><span>＋</span> View attendance</a></div><div class="section-heading"><div><h2>Today at a glance</h2><p>Live attendance overview</p></div><span class="live-indicator"><i></i> Updated just now</span></div><div class="row g-3 stats-row"><?php foreach([['Total students',$total,'Enrolled students','♙','blue'],['Present today',$counts['Present'],'Checked in today','✓','green'],['Late arrivals',$counts['Late'],'Arrived after class start','◷','amber'],['Absent today',$counts['Absent'],'No check-in recorded','−','red']] as [$label,$value,$note,$icon,$tone]):?><div class="col-12 col-sm-6 col-xl-3"><article class="stat-card"><div class="stat-top"><span><?=e($label)?></span><span class="stat-icon icon-<?=$tone?>"><?=$icon?></span></div><div class="stat-value"><?=number_format($value)?></div><div class="stat-foot"><span class="stat-<?=$tone?>">●</span> <?=e($note)?></div><div class="stat-accent accent-<?=$tone?>"></div></article></div><?php endforeach?></div><section class="content-card activity-card"><div class="card-heading"><div><h2>Recent activity</h2><p>The latest student attendance records</p></div><a class="subtle-link" href="attendance_logs.php">View all activity <span>→</span></a></div><div class="table-responsive"><table class="table activity-table"><thead><tr><th>STUDENT</th><th>STUDENT ID</th><th>COURSE & YEAR</th><th>TIME IN</th><th>STATUS</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="5" class="empty-state">No attendance activity yet. Records will appear here once students check in.</td></tr><?php else:foreach($recent as $r):?><tr><td><div class="student-cell"><span class="avatar student-avatar"><?=e(strtoupper(substr($r['name'],0,1)))?></span><strong><?=e($r['name'])?></strong></div></td><td class="table-secondary-text"><?=e($r['student_id_no'])?></td><td class="table-secondary-text"><?=e($r['course_year'])?></td><td class="table-secondary-text"><?=$r['time_in']?e(date('g:i A',strtotime($r['time_in']))):'—'?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;endif?></tbody></table></div><div class="table-footer"><span>Showing latest <?=count($recent)?> records</span><a href="attendance_logs.php">Open attendance report <span>→</span></a></div></section><?php page_end();
